 * The two limiter policy kinds. Each keeps one independent state per key and
 * exposes the advance/allow/record protocol the engine drives.
 */

/**
 * A token bucket. Tokens are tracked in units of 1/per of a token so that
 * refills over partial periods stay exact, matching the specification's
 * "n ticks yields refill*n/per more tokens, never rounded away".
 */
export class TokenBucket {
  constructor({ capacity, refill, per }) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityUnits = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      this.states.set(key, { lastTick: tick, tokenUnits: this.capacityUnits })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      let tokenUnits = state.tokenUnits + this.refill * delta
      if (tokenUnits > this.capacityUnits) tokenUnits = this.capacityUnits
      state.tokenUnits = tokenUnits
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).tokenUnits >= this.per
  }

  record(key) {
    this.states.get(key).tokenUnits -= this.per
  }
}

/** A sliding window over the ticks it recorded for each key. */
export class SlidingWindow {
  constructor({ limit, span }) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    while (state.ticks.length > 0 && state.ticks[0] <= threshold) state.ticks.shift()
  }

  allow(key) {
    return BigInt(this.states.get(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).ticks.push(tick)
  }
}
"}

