/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseLimiterFile, ParseError } from './parser.js'
import { runEngine } from './engine.js'

function usageFail() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    usageFail()
    return
  }

  const input = readFileSync(0, 'utf8')

  let model
  try {
    model = parseLimiterFile(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  const results = runEngine(model)

  if (mode === 'replay') {
    let out = ''
    for (const result of results) {
      out += result.allowed
        ? `${result.tick} ${result.key} allow\n`
        : `${result.tick} ${result.key} deny ${result.denyPolicy}\n`
    }
    process.stdout.write(out)
  } else {
    const totals = new Map()
    for (const result of results) {
      let entry = totals.get(result.key)
      if (!entry) {
        entry = { allowed: 0, denied: 0 }
        totals.set(result.key, entry)
      }
      if (result.allowed) entry.allowed++
      else entry.denied++
    }
    const keys = [...totals.keys()].sort()
    let out = ''
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const entry = totals.get(key)
      out += `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
      totalAllowed += entry.allowed
      totalDenied += entry.denied
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
"}

